#include "Halide.h"

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "gesummv.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A, B, x and scalars alpha, beta exactly as in the
 * original PolyBench C version.
 *
 * C layout:
 *   A[i][j], B[i][j] with i as row, j as column.
 *
 * Halide layout:
 *   Buffer<num_t,2> A(j, i)
 *   Buffer<num_t,2> B(j, i)
 *   Buffer<num_t,1> x(i)
 *
 * i is the slow (row) dimension, j is the fast (column) dimension.
 */
static
void init_array(int n,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B,
                Halide::Buffer<num_t, 1> x) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    Func init_A("init_A"), init_B("init_B"), init_x("init_x");

    // x[i] = (i % n) / n;
    init_x(i) = cast<num_t>(i % n) / cast<int>(n);

    // A[i][j] = ((i * j + 1) % n) / n;
    // Stored as A(j, i) in the Buffer.
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // B[i][j] = ((i * j + 2) % n) / n;
    // Stored as B(j, i) in the Buffer.
    init_B(j, i) = cast<num_t>((i * j + 2) % n) / cast<int>(n);

    // Simple, one-shot initialization; we keep the default schedule here.
    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    //  - A, B are N x N matrices, stored as (j, i) = (column, row)
    //  - x, y are N-length vectors.
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for A, B, x to feed into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data.
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // ------------------------------------------------------------------
    // Optimized Halide pipeline for GESUMMV
    //
    // Mathematical kernel (per row i):
    //   tmpA(i) = sum_j A[i, j] * x[j]
    //   tmpB(i) = sum_j B[i, j] * x[j]
    //   y[i]    = alpha * tmpA(i) + beta * tmpB(i)
    //
    // Buffers store A,B as (j, i) so that j is the fast (contiguous)
    // dimension. We use a single reduction Func that returns a Tuple
    // of two accumulators, so that:
    //   - we traverse each row of A and B only once,
    //   - we load x(j) only once per j,
    //   - we still preserve the original i-outer, j-inner sum order.
    // ------------------------------------------------------------------

    Var i("i");
    RDom j(0, A.dim(0).extent(), "j");  // j runs over columns (fast dimension)

    // accum(i) = { sum_j A(i,j)*x(j), sum_j B(i,j)*x(j) }
    Func accum("accum");
    // Pure definition: initialize both accumulators to zero.
    accum(i) = Tuple(cast<num_t>(0), cast<num_t>(0));

    // Reduction update: fused double dot-product.
    //
    // We must build the new Tuple from the old values explicitly, as per
    // Halide's tuple reduction rules (see tutorial lesson 13).
    Expr accA = accum(i)[0] + A_param(j, i) * x_param(j);
    Expr accB = accum(i)[1] + B_param(j, i) * x_param(j);
    accum(i) = Tuple(accA, accB);

    // Final combination into y:
    Func y_func("y_func");
    y_func(i) = Expr(alpha) * accum(i)[0] + Expr(beta) * accum(i)[1];

    // ------------------------------------------------------------------
    // Schedule
    //
    // Goals:
    //   * Keep j as the innermost loop to exploit contiguous access in A,B,x.
    //   * Fuse the two dot-products so that A,B,x are streamed once.
    //   * Parallelize over i (rows) across CPU cores.
    //   * Keep extra memory usage minimal (only scalar accumulators per row).
    // ------------------------------------------------------------------

    // Tile and parallelize over the row dimension.
    //
    // Split i into tiles of size 64: i = io * 64 + ii.
    // We then parallelize across io, so each worker thread processes
    // a chunk of 64 consecutive rows. This gives coarse-grain work units
    // with good cache locality per thread.
    Var io("io"), ii("ii");
    const int tile_i = 64;

    y_func
        .split(i, io, ii, tile_i)
        .parallel(io);
    // We deliberately *do not* vectorize over i, because memory for A,B
    // is laid out as (j, i), making j the fast dimension. Vectorizing
    // over i would lead to strided/gather loads.

    // We rely on Halide's default schedule for 'accum' in this producer–
    // consumer relationship:
    //
    //  - 'accum' is a reduction Func (has an update definition).
    //  - 'y_func' is the final pipeline stage and calls 'accum(i)'.
    //
    // The default is to compute 'accum' per value of the pure variable 'i'
    // at the innermost loop of its consumer. Combined with the schedule
    // above, the generated code for the core will look conceptually like:
    //
    //   parallel for (io) {
    //       for (ii in 0..tile_i-1) {
    //           i = io * tile_i + ii;
    //           // accum(i).pure: set both accumulators to 0
    //           accA = 0;
    //           accB = 0;
    //           // accum(i).update: reduction over j
    //           for (j in 0..n-1) {
    //               valA = A(j, i);
    //               valB = B(j, i);
    //               xv  = x(j);
    //               accA += valA * xv;
    //               accB += valB * xv;
    //           }
    //           // y_func(i): final combination
    //           y(i) = alpha * accA + beta * accB;
    //       }
    //   }
    //
    // This:
    //   - Preserves the original reduction order over j for each i.
    //   - Streams each row of A and B, and the vector x, with unit stride.
    //   - Uses two scalar accumulators per row in registers, not arrays.
    //   - Exploits multi-core parallelism across tiles of rows.
    //
    // If desired, additional micro-optimizations like unrolling the
    // reduction variable j can be added as:
    //
    //   RVar jo("jo"), ji("ji");
    //   accum.update().split(j, jo, ji, 4).unroll(ji);
    //
    // but we keep the schedule simple and robust here.

    // Compile the kernel to machine code.
    y_func.compile_jit();

    // Measure execution time.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination and allow checking).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print timing in seconds on stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
