    // --- Simple but effective initialization schedule ----------------------
    //
    // We only run initialization once, but for large N it is still worth
    // vectorizing across the fast (contiguous) dimension to reduce time.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // x is 1D; vectorize along i (contiguous).
    init_x.compute_root()
          .vectorize(i, vec_width);

    // A and B are 2D; dimension 0 (j) is contiguous, so vectorize across j.
    init_A.compute_root()
          .vectorize(j, vec_width);

    init_B.compute_root()
          .vectorize(j, vec_width);
    // -----------------------------------------------------------------------

    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    //  - A, B are N x N matrices, stored as (j, i) = (column, row)
    //  - x, y are N-length vectors.
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for A, B, x to feed into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data.
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // Halide vars and reduction domain.
    Var i("i");
    // j runs over columns (fast dimension, Buffer dim 0).
    RDom j_dom(0, A.dim(0).extent(), "j");

    // -----------------------------------------------------------------------
    // Optimized GESUMMV pipeline
    //
    // Mathematical operation (per row i):
    //   tmp[i]   = sum_j A[i,j] * x[j]
    //   y_acc[i] = sum_j B[i,j] * x[j]
    //   y[i]     = alpha * tmp[i] + beta * y_acc[i]
    //
    // We fuse the two reductions into a single Tuple-valued Func 'acc':
    //   acc(i) = { tmp[i], y_acc[i] }
    // so that A, B, and x are each streamed once per row, reusing x[j]
    // for both dot-products. This preserves the original semantics while
    // reducing memory traffic and improving locality.
    // -----------------------------------------------------------------------
    Func acc("acc"), y_func("y_func");

    Expr zero = cast<num_t>(0);

    // Pure definition: initialize both accumulators to zero.
    acc(i) = Tuple(zero, zero);

    // Update definition: fused reduction over j.
    //
    // Note: The update definition references acc(i)[0] and acc(i)[1]
    // using the same pure variable 'i' on both LHS and RHS, which
    // satisfies Halide's reduction constraints.
    Expr a_ij = A_param(j_dom, i);
    Expr b_ij = B_param(j_dom, i);
    Expr x_j  = x_param(j_dom);

    acc(i) = Tuple(
        acc(i)[0] + a_ij * x_j,  // accumulate A[i,j] * x[j]
        acc(i)[1] + b_ij * x_j   // accumulate B[i,j] * x[j]
    );

    // Final combination:
    y_func(i) = Expr(alpha) * acc(i)[0] + Expr(beta) * acc(i)[1];

    // -----------------------------------------------------------------------
    // Schedule
    //
    // Goal:
    //   - Parallelize across rows (i) to use many cores.
    //   - Vectorize across j (the fast dimension) to exploit SIMD.
    //   - Keep accumulators in registers; only acc(i) is stored once per row.
    //   - Preserve i-outer, j-inner semantics for good locality.
    // -----------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Tile size for rows. Chosen conservatively; can be tuned per machine.
    const int tile_i = std::min(n, 128);

    // Schedule for the fused reduction 'acc'.
    Var io("io"), ii("ii");
    RVar j("j");  // alias for the RDom variable inside j_dom

    acc.compute_root();

    // Pure definition (initialization to zero):
    //   for io in tiles of rows (parallel)
    //     for ii in rows inside tile
    //       acc(i) = {0, 0}
    acc.split(i, io, ii, tile_i)
       .parallel(io);

    // Update step (the actual reduction):
    //
    // Loop structure after the schedule conceptually becomes:
    //   parallel for io:
    //     for ii:
    //       for j:
    //         acc(i).0 += A_param(j, i) * x_param(j)
    //         acc(i).1 += B_param(j, i) * x_param(j)
    //
    // where i = io * tile_i + ii. j is innermost and vectorized.
    acc.update()
       .split(i, io, ii, tile_i)
       .parallel(io)
       .vectorize(j_dom, vec_width);

    // Schedule for the final y_func:
    //
    // This stage is cheap compared to the O(n^2) work above, but we still
    // parallelize and vectorize for completeness.
    Var yo("yo"), yi("yi");
    y_func.compute_root()
          .split(i, yo, yi, tile_i)
          .parallel(yo)
          .vectorize(yi, vec_width);

    // Compile the kernel to machine code.
    y_func.compile_jit(target);

    // Measure execution time.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    y_func.realize(y);

