    init_x(i) = cast<num_t>(i % n) / cast<int>(n);

    // A[i][j] = ((i * j + 1) % n) / n;
    // Stored as A(j, i) in the Buffer.
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // B[i][j] = ((i * j + 2) % n) / n;
    // Stored as B(j, i) in the Buffer.
    init_B(j, i) = cast<num_t>((i * j + 2) % n) / cast<int>(n);

    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    //  - A, B are N x N matrices, stored as (j, i) = (column, row)
    //  - x, y are N-length vectors.
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for A, B, x to feed into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data.
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // -------------------------
    // Halide computation
    // -------------------------

    // We compute:
    //   y[i] = alpha * sum_j A[i, j] * x[j] + beta * sum_j B[i, j] * x[j]
    //
    // In terms of our Buffer layout, A(j, i) and B(j, i) store A[i][j] and B[i][j],
    // so j (dimension 0) is contiguous and is the natural SIMD dimension.
    //
    // We *fuse* the two dot products into a single reduction over j:
    //   y[i] = sum_j (alpha * A[i, j] * x[j] + beta * B[i, j] * x[j])
    // which is algebraically equivalent to the original formulation, and
    // lets us load x[j] only once per j and reuse it for both A and B.

    Var i("i");
    RDom j(0, A.dim(0).extent(), "j");  // j runs over columns (contiguous dim)

    Func y_func("y_func");

    // Initialize reduction: one accumulator per output element y[i].
    y_func(i) = cast<num_t>(0);

    // Fused reduction over j:
    //   y[i] += alpha * A[i,j] * x[j] + beta * B[i,j] * x[j]
    // This traverses each row of A and B exactly once and shares x[j] loads.
    y_func(i) += Expr(alpha) * A_param(j, i) * x_param(j) +
                 Expr(beta)  * B_param(j, i) * x_param(j);

    // -------------------------
    // Scheduling for performance
    // -------------------------

    // We target the host (respecting HL_TARGET etc.) so that we can query
    // the natural vector width for the current CPU and data type.
    Target target = get_jit_target_from_environment();
    int vec_j = target.natural_vector_size(type_of<num_t>());
    if (vec_j < 1) {
        vec_j = 1;
    }

    // 1. Compute y_func at the root level so we can parallelize across rows.
    y_func.compute_root();

    // 2. Parallelize across the row index i.
    //
    //    Each output element y[i] depends only on row i of A and B and the
    //    shared vector x, so rows are fully independent and safe to compute
    //    in parallel. This exposes coarse-grain parallelism across cores.
    //
    //    We parallelize the reduction update so that each thread owns a set
    //    of i-values and performs the full dot-product over j for each row.
    y_func.update()
          .parallel(i);

    // 3. Vectorize along the reduction dimension j.
    //
    //    For fixed (i), A_param(j, i), B_param(j, i), and x_param(j) are all
    //    contiguous in j (dimension 0), so vectorizing j generates wide SIMD
    //    loads and FMAs over the dot-product. Halide will handle any remainder
    //    iterations with a scalar tail loop.
    y_func.update()
          .vectorize(j, vec_j);

    // Compile the kernel to machine code with the chosen target.
    y_func.compile_jit(target);

    // Measure execution time.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination and allow checking).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print timing in seconds on stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
