 *
 * C layout:
 *   A[i][j], B[i][j] with i as row, j as column.
 *
 * Halide layout:
 *   Buffer<num_t,2> A(j, i)
 *   Buffer<num_t,2> B(j, i)
 *   Buffer<num_t,1> x(i)
 *
 * i is the slow (row) dimension, j is the fast (column) dimension.
 */
static
void init_array(int n,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B,
                Halide::Buffer<num_t, 1> x) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    Func init_A("init_A"), init_B("init_B"), init_x("init_x");

    // x[i] = (i % n) / n;
    init_x(i) = cast<num_t>(i % n) / cast<int>(n);

    // A[i][j] = ((i * j + 1) % n) / n;
    // Stored as A(j, i) in the Buffer.
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // B[i][j] = ((i * j + 2) % n) / n;
    // Stored as B(j, i) in the Buffer.
    init_B(j, i) = cast<num_t>((i * j + 2) % n) / cast<int>(n);

    // For initialization the default schedule is typically sufficient.
    // The cost is minor compared to the main kernel, so we keep it simple.
    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    //  - A, B are N x N matrices, stored as (j, i) = (column, row)
    //  - x, y are N-length vectors.
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for A, B, x to feed into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data.
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // ------------------------------
    // GESUMMV computation in Halide:
    //   y[i] = alpha * sum_j A[i,j]*x[j] + beta * sum_j B[i,j]*x[j]
    //
    // We fuse the two dot-products into a single reduction to:
    //   - walk each row of A and B only once,
    //   - load x[j] once per j and reuse it,
    //   - reduce memory traffic and improve bandwidth utilization.
    // ------------------------------

    Var i("i");
    // j runs over columns (fast dimension in the Buffers).
    RDom j(0, A.dim(0).extent(), "j");

    Func y_func("y_func");

    // Initialize reduction result.
    y_func(i) = cast<num_t>(0);

    // Fused reduction over j:
    //   y[i] += alpha * A[i,j] * x[j] + beta * B[i,j] * x[j]
    // which is mathematically:
    //   y[i] = alpha * sum_j A[i,j]*x[j] + beta * sum_j B[i,j]*x[j]
    // (same as the original kernel, up to floating-point associativity).
    Expr a_ij = A_param(j, i);
    Expr b_ij = B_param(j, i);
    Expr x_j  = x_param(j);

    y_func(i) += Expr(alpha) * a_ij * x_j +
                 Expr(beta)  * b_ij * x_j;

    // ------------------------------
    // Scheduling: improve locality, SIMD, and multicore usage.
    // ------------------------------

    // Query the JIT target to choose a good SIMD width for the element type.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Tile the output dimension i to create coarse-grain work units
    // and then parallelize across tiles. Each row i is independent.
    Var io("io"), ii("ii");
    // Split i into [io, ii] with a moderate tile size for cache & load-balance.
    const int tile_i = 64;

    y_func.compute_root();
    y_func.split(i, io, ii, tile_i)
          .parallel(io);  // distribute row-tiles across cores

    // Now optimize the reduction over j:
    // - split j for explicit vectorization,
    // - keep j as the innermost data dimension to get unit-stride loads.
    RVar jo("jo"), ji("ji");
    y_func.update()
          .split(j, jo, ji, vec_width) // j = jo * vec_width + ji
          // Order from innermost outwards: ji (vector lane), jo, ii, io.
          .reorder(ji, jo, ii, io)
          .vectorize(ji);              // SIMD across contiguous columns j

    // At this point the conceptual native loop nest for the update is:
    //
    //   parallel for io:
    //     for ii in [0, tile_i):
    //       for jo:
    //         vectorized for ji in [0, vec_width):
    //           i = io*tile_i + ii
    //           j = jo*vec_width + ji
    //           y[i] += alpha*A[j,i]*x[j] + beta*B[j,i]*x[j]
    //
    // This preserves the original i-outer, j-inner traversal but:
    //   - exploits SIMD over j (contiguous in memory),
    //   - spreads work across tiles of i on many cores,
    //   - keeps per-row accumulators in registers only (no tmp arrays).

    // Compile the kernel to machine code for the chosen target.
    y_func.compile_jit(target);

    // Measure execution time (only the realize call is timed).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination and allow checking).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print timing in seconds on stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
